package pogreb

import (
	"errors"
	"sync"
)

// ErrIterationDone is returned by ItemIterator.Next calls when there are no more items to return.
var ErrIterationDone = errors.New("no more items in iterator")

type item struct {
	key   []byte
	value []byte
}

// ItemIterator is an iterator over DB key-value pairs. It iterates the items in an unspecified order.
type ItemIterator struct {
	db            *DB
	nextBucketIdx uint32
	queue         []item
	mu            sync.Mutex
}

// fetchItems adds items to the iterator queue from a bucket located at nextBucketIdx.
func (it *ItemIterator) fetchItems(nextBucketIdx uint32) error {
	bit := it.db.index.newBucketIterator(nextBucketIdx)
	for {
		b, err := bit.next()
		if err == ErrIterationDone {
			return nil
		}
		if err != nil {
			return err
		}
		for i := 0; i < slotsPerBucket; i++ {
			sl := b.slots[i]
			if sl.offset == 0 {
				// No more items in the bucket.
				break
			}

			// Check if the key still exists in the index (not deleted)
			key, err := it.db.datalog.readKey(sl)
			if err != nil {
				return err
			}

			exists, err := it.db.Has(key)
			if err != nil {
				return err
			}

			// Only add to queue if the key still exists (not deleted)
			if exists {
				value, err := it.db.datalog.readKeyValue(sl)
				if err != nil {
					return err
				}
				key = cloneBytes(key)
				value = cloneBytes(value[1]) // value is returned as second element from readKeyValue
				it.queue = append(it.queue, item{key: key, value: value})
			}
		}
	}
}

