	it.mu.Lock()
	defer it.mu.Unlock()

	for len(it.queue) == 0 {
		if it.nextBucketIdx >= it.db.index.numBuckets {
			return nil, nil, ErrIterationDone
		}
		if err := it.fetchItems(it.nextBucketIdx); err != nil {
			return nil, nil, err
		}
		it.nextBucketIdx++
	}

