func TestIteratorDoesNotReturnDeletedItems(t *testing.T) {
	// Use in-memory filesystem for testing
	opts := &Options{
		FileSystem: fs.Mem,
	}

	db, err := Open("test.db", opts)
	assert.Nil(t, err)
	defer db.Close()

