		err := db.Put([]byte(k), []byte(v))
		assert.Nil(t, err)
	}

	// Verify all items are there
	assert.Equal(t, uint32(4), db.Count())

	// Delete some items
	err = db.Delete([]byte("key2"))
	assert.Nil(t, err)

	err = db.Delete([]byte("key4"))
	assert.Nil(t, err)

	// Verify count is updated
	assert.Equal(t, uint32(2), db.Count())

	// Iterate over items and verify deleted items are not returned
	it := db.Items()
	count := 0
	iteratedItems := make(map[string]string)

